        tk.Label(foot, text=f"● {PLAT_LABEL.get(OS_NAME, OS_NAME)} (this computer)\n   {'administrator' if admin else 'standard user'}", font=F["tiny"], bg=C("side"), fg=C("dim"), justify="left").pack(anchor="w", pady=(10, 0))

        # main column
