        cv.bind("<Configure>", relayout)
        inner.bind("<Configure>", lambda e: cv.configure(scrollregion=cv.bbox("all")))

        # detail panel
        W["detail"] = tk.Frame(app, bg=C("side"), width=352)
        W["detail"].grid(row=0, column=2, sticky="ns")
